-- Every exercise has its own scene now; the old shared poses move over, and
-- the pushdown was always the straight-arm lat pushdown.
UPDATE "exercises" SET "name" = 'Lat Pushdown', "muscle_group" = 'pull', "path" = 0.6 WHERE "name" = 'Pushdown';--> statement-breakpoint
UPDATE "exercises" SET "pose" = CASE "name" WHEN 'Bench Press' THEN 'bench' WHEN 'Incline Bench' THEN 'incline' WHEN 'Chest Press' THEN 'chestpress' WHEN 'Weighted Dips' THEN 'dips' WHEN 'Cable Fly' THEN 'cablefly' WHEN 'Machine Fly' THEN 'machinefly' WHEN 'Tricep Ext' THEN 'tricep' WHEN 'Lat Pushdown' THEN 'latpush' WHEN 'Muscle Ups' THEN 'muscleup' WHEN 'Weighted Pullup' THEN 'pullup' WHEN 'Lat Pulldown' THEN 'pulldown' WHEN '1-Arm Pulldown' THEN 'onearm' WHEN 'Cable Row' THEN 'cablerow' WHEN 'Barbell Row' THEN 'bbrow' WHEN 'Chest Sup Row' THEN 'chestsup' WHEN 'Row Machine' THEN 'rowmachine' WHEN 'Reverse Fly' THEN 'reversefly' WHEN 'Egyptian Raise' THEN 'egyptian' WHEN 'Preacher Curl' THEN 'preacher' WHEN 'Bayesian Curl' THEN 'bayesian' WHEN 'Deadlift' THEN 'deadlift' WHEN 'Core' THEN 'core' ELSE CASE "pose" WHEN 'press' THEN 'chestpress' WHEN 'fly' THEN 'machinefly' WHEN 'dip' THEN 'dips' WHEN 'hang' THEN 'pulldown' WHEN 'row' THEN 'cablerow' WHEN 'curl' THEN 'preacher' WHEN 'raise' THEN 'egyptian' WHEN 'run' THEN 'jog' ELSE "pose" END END;
